import json

def transform(grid):
    rows = len(grid)
    cols = len(grid[0]) if grid else 0
    result = [row[:] for row in grid]

    for r in range(rows):
        for c in range(cols):
            val = grid[r][c]
            if val == 1:
                continue

            if val == 2:
                offset = 4
                num_ones_below = 3
            elif val == 8:
                offset = 3
                num_ones_below = 2
            else:
                continue

            new_r = r - offset
            if 0 <= new_r < rows:
                result[new_r][c] = val
                for i in range(1, num_ones_below + 1):
                    if new_r + i < rows:
                        result[new_r + i][c] = 1
    return result

